<script>import {router} from '../../../router.js';import {authStore} from '../../auth/states/authStore.js';let {children}= $props();const nav=[{label:'Semua Link Tree',path:'/',icon:'▦'},{label:'Profil',path:'/profile',icon:'◉'},{label:'Pengguna',path:'/users',icon:'♙'}];</script>
<div class="app-shell"><header class="topbar"><a href="/" class="brand" onclick={(e)=>{e.preventDefault();router.navigate('/')}}><img src="/logo.svg" alt="" width="38" height="38"/><span>Delcom <b>Link Tree</b></span></a><div class="topbar-right"><span class="user-chip">{authStore.user?.name||authStore.user?.username||'Akun Delcom'}</span><button class="btn btn-light btn-small" onclick={()=>{authStore.clear();router.navigate('/auth/login')}}>Keluar</button></div></header><div class="app-body"><aside class="sidebar"><p class="side-label">WORKSPACE</p>{#each nav as item}<a class:active={router.path===item.path} href={item.path} onclick={(e)=>{e.preventDefault();router.navigate(item.path)}}><span class="nav-icon" aria-hidden="true">{item.icon}</span>{item.label}</a>{/each}<div class="sidebar-tip"><span>✦</span><strong>Lebih teratur.</strong><p>Kumpulkan tautan penting dalam satu koleksi.</p></div></aside><main class="main-content">{@render children?.()}</main></div></div>
